-- CreateTable: initial schema for the RUET fee-payment system.
-- Semester is stored as a RUET term code (TEXT, e.g. "1_ODD" = 1st Odd).
-- Generated by hand from prisma/schema.prisma (prisma migrate diff could
-- not run in the sandbox: the Prisma engine download was blocked there).
-- On a normal network, `npx prisma migrate dev` produces the same shape.

CREATE TYPE "FeeType" AS ENUM ('SEMESTER_FINAL', 'COURSE_REGISTRATION');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING', 'COMPLETED', 'FAILED', 'CANCELLED');

CREATE TABLE "departments" (
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "departments_pkey" PRIMARY KEY ("code")
);

CREATE TABLE "students" (
    "id" TEXT NOT NULL,
    "roll" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "email" TEXT,
    "departmentCode" TEXT NOT NULL,
    "passwordHash" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "students_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "courses" (
    "id" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "credits" DOUBLE PRECISION NOT NULL,
    "semester" TEXT NOT NULL,
    "departmentCode" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "courses_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "payments" (
    "id" TEXT NOT NULL,
    "tranId" TEXT NOT NULL,
    "valId" TEXT,
    "studentRoll" TEXT NOT NULL,
    "departmentCode" TEXT NOT NULL,
    "semester" TEXT NOT NULL,
    "feeType" "FeeType" NOT NULL,
    "totalCredits" DOUBLE PRECISION NOT NULL,
    "amountBdt" DECIMAL(10,2) NOT NULL,
    "status" "PaymentStatus" NOT NULL DEFAULT 'PENDING',
    "coursesJson" JSONB NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "completedAt" TIMESTAMP(3),
    CONSTRAINT "payments_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "students_roll_key" ON "students"("roll");
CREATE UNIQUE INDEX "courses_code_departmentCode_semester_key" ON "courses"("code", "departmentCode", "semester");
CREATE INDEX "courses_departmentCode_semester_idx" ON "courses"("departmentCode", "semester");
CREATE UNIQUE INDEX "payments_tranId_key" ON "payments"("tranId");
CREATE UNIQUE INDEX "payments_studentRoll_departmentCode_semester_feeType_key" ON "payments"("studentRoll", "departmentCode", "semester", "feeType");
CREATE INDEX "payments_departmentCode_semester_feeType_idx" ON "payments"("departmentCode", "semester", "feeType");
CREATE INDEX "payments_studentRoll_idx" ON "payments"("studentRoll");

ALTER TABLE "students" ADD CONSTRAINT "students_departmentCode_fkey" FOREIGN KEY ("departmentCode") REFERENCES "departments"("code") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "courses" ADD CONSTRAINT "courses_departmentCode_fkey" FOREIGN KEY ("departmentCode") REFERENCES "departments"("code") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payments" ADD CONSTRAINT "payments_studentRoll_fkey" FOREIGN KEY ("studentRoll") REFERENCES "students"("roll") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "payments" ADD CONSTRAINT "payments_departmentCode_fkey" FOREIGN KEY ("departmentCode") REFERENCES "departments"("code") ON DELETE RESTRICT ON UPDATE CASCADE;
